UPDATE source_documents old SET superseded_by_document_id=replacement.id FROM source_documents replacement WHERE old.project_id=$1 AND old.freshness_status='superseded' AND replacement.project_id=old.project_id AND replacement.is_current AND replacement.freshness_status='current' AND replacement.path=CASE WHEN old.path LIKE 'superseded/%' THEN substring(old.path FROM 12) ELSE replace(old.path,'/superseded/','/') END
